installer-gui-script.script:
function pm_install_check() {
    if (system.compareVersions(system.version.ProductVersion, '12.0') < 0) {
        my.result.title = 'macOS 12.0+ Required';
        my.result.message = 'MedForge requires macOS 12.0 (Monterey) or later.';
        my.result.type = 'Fatal';
        return false;
    }
    return true;
}
